using UnityEngine;
namespace TowerDefenseIncremental { public sealed class Enemy : MonoBehaviour, IDamageable { private GameManager game; private Vector2[] path; private float speed; private int leakDamage; private int waypoint; private Health health; public bool IsDead => health == null || health.IsDead; public float PathProgress => waypoint + (waypoint < path.Length - 1 ? 1f - Vector2.Distance(transform.position, path[waypoint + 1]) / Vector2.Distance(path[waypoint], path[waypoint + 1]) : 0f); public void Initialize(GameManager owner, Vector2[] route, int hp, float moveSpeed, int leak) { game = owner; path = route; speed = moveSpeed; leakDamage = leak; health = gameObject.AddComponent<Health>(); health.Initialize(hp); health.Died += Die; } private void Update() { if (IsDead) return; var goal = path[waypoint + 1]; transform.position = Vector2.MoveTowards(transform.position, goal, speed * Time.deltaTime); if (Vector2.Distance(transform.position, goal) < .01f && ++waypoint >= path.Length - 1) Escape(); } public void TakeDamage(int amount) => health.Damage(amount); private void Die() { game.EnemyDefeated(this, 8); Destroy(gameObject); } private void Escape() { game.EnemyEscaped(this, leakDamage); Destroy(gameObject); } } }
